-- M7 Query Store performance evidence. Append-only, passive, no target SQL is executed by this migration.
SET LOCAL lock_timeout = '5s'; SET LOCAL statement_timeout = '5min'; SET LOCAL idle_in_transaction_session_timeout = '5min'; SET LOCAL TIME ZONE 'UTC'; SET LOCAL ROLE sqlobserver_migrator;

