CREATE TYPE events.query_performance_source AS ENUM ('query_store','plan_cache','mixed','unavailable');
REVOKE ALL ON TYPE events.query_performance_source FROM PUBLIC;
GRANT USAGE ON TYPE events.query_performance_source TO sqlobserver_collector,sqlobserver_server,sqlobserver_migrator;
CREATE TABLE events.query_performance_run (collection_run_id uuid NOT NULL REFERENCES telemetry.collection_run(run_id), instance_id uuid NOT NULL REFERENCES control.observation_target(instance_id), target_revision bigint NOT NULL, window_start timestamptz NOT NULL, window_end timestamptz NOT NULL, source events.query_performance_source NOT NULL, source_state text NOT NULL, coverage text NOT NULL, freshness boolean NOT NULL, truncated boolean NOT NULL, target_status text, target_reason text, completion_digest bytea NOT NULL, committed_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY (collection_run_id), CHECK (target_revision > 0 AND octet_length(completion_digest)=32), CHECK (window_end > window_start AND window_end - window_start <= interval '7 days'), CHECK (source_state IN ('read_write','read_only','disabled','unsupported','permission_denied','read_failure','timed_out','mixed') OR source_state='unavailable'), CHECK (coverage IN ('complete','truncated','unavailable','no_activity')), CHECK ((source_state='unavailable') = (target_status IS NOT NULL)), CHECK ((target_status IS NULL AND target_reason IS NULL) OR (target_status,target_reason) IN (('inventory_failure','inventory_read_failure'),('connection_failure','transient_target_failure'),('connection_failure','permanent_target_failure'),('connection_failure','required_permission_missing'),('deadline_exceeded','deadline_exceeded'),('circuit_open','circuit_currently_open'),('unsupported','target_unsupported'),('unsupported','target_version_unsupported'),('unsupported','target_platform_unsupported'),('unsupported','target_edition_unsupported'),('unsupported','capability_profile_missing'),('unsupported','capability_profile_stale'),('unsupported','capability_missing'),('output_invalid','output_validation_failed'),('lease_lost','lease_ownership_lost'))));

CREATE TABLE events.query_performance_query (collection_run_id uuid NOT NULL REFERENCES events.query_performance_run(collection_run_id) ON DELETE CASCADE, instance_id uuid NOT NULL, database_id integer NOT NULL, query_fingerprint bytea NOT NULL, PRIMARY KEY (collection_run_id,database_id,query_fingerprint), CHECK (database_id BETWEEN 1 AND 32767), CHECK (octet_length(query_fingerprint)=32));
CREATE TABLE events.query_performance_plan (collection_run_id uuid NOT NULL, database_id integer NOT NULL, query_fingerprint bytea NOT NULL, plan_fingerprint bytea NOT NULL, PRIMARY KEY (collection_run_id,database_id,query_fingerprint,plan_fingerprint), FOREIGN KEY (collection_run_id,database_id,query_fingerprint) REFERENCES events.query_performance_query(collection_run_id,database_id,query_fingerprint) ON DELETE CASCADE, CHECK (octet_length(plan_fingerprint)=32));
CREATE TABLE events.query_performance_observation (collection_run_id uuid NOT NULL, database_id integer NOT NULL, query_fingerprint bytea NOT NULL, plan_fingerprint bytea, observation_key bytea NOT NULL, source events.query_performance_source NOT NULL, source_state text NOT NULL, interval_start timestamptz NOT NULL, interval_end timestamptz NOT NULL, observed_at timestamptz NOT NULL, semantics text NOT NULL, cpu_ms bigint, duration_ms bigint, execution_count bigint, logical_reads bigint, writes bigint, rows_processed bigint, PRIMARY KEY (collection_run_id,database_id,query_fingerprint,observation_key), FOREIGN KEY (collection_run_id,database_id,query_fingerprint) REFERENCES events.query_performance_query(collection_run_id,database_id,query_fingerprint) ON DELETE CASCADE, CHECK (octet_length(observation_key)=16), CHECK (source IN ('query_store','plan_cache')), CHECK (source_state IN ('read_write','read_only','disabled','unsupported','permission_denied','read_failure','timed_out')), CHECK (interval_end > interval_start AND interval_end-interval_start <= interval '7 days'), CHECK (cpu_ms IS NULL OR cpu_ms >= 0), CHECK (duration_ms IS NULL OR duration_ms >= 0), CHECK (execution_count IS NULL OR execution_count >= 0), CHECK (logical_reads IS NULL OR logical_reads >= 0), CHECK (writes IS NULL OR writes >= 0), CHECK (rows_processed IS NULL OR rows_processed >= 0), CHECK (semantics IN ('query_store_interval','plan_cache_cumulative','plan_cache_delta','plan_cache_baseline','reset')));
CREATE TABLE events.query_performance_cache_baseline (instance_id uuid NOT NULL REFERENCES control.observation_target(instance_id), database_id integer NOT NULL, query_fingerprint bytea NOT NULL, plan_fingerprint bytea NOT NULL DEFAULT decode(repeat('00',32),'hex'), cumulative_executions bigint NOT NULL, cumulative_cpu_ms bigint NOT NULL, last_seen_at timestamptz NOT NULL, reset_generation bigint NOT NULL DEFAULT 0, PRIMARY KEY (instance_id,database_id,query_fingerprint,plan_fingerprint), CHECK (octet_length(query_fingerprint)=32 AND octet_length(plan_fingerprint)=32 AND database_id BETWEEN 1 AND 32767), CHECK (cumulative_executions >= 0 AND cumulative_cpu_ms >= 0));
CREATE TABLE events.query_performance_stage (collection_run_id uuid NOT NULL, instance_id uuid NOT NULL, database_id integer NOT NULL, payload jsonb NOT NULL, payload_bytes integer NOT NULL, PRIMARY KEY (collection_run_id,database_id), CHECK (jsonb_typeof(payload)='object' AND payload_bytes BETWEEN 1 AND 8388608));
CREATE TABLE events.query_performance_content_link (collection_run_id uuid NOT NULL, instance_id uuid NOT NULL, database_id integer NOT NULL, query_fingerprint bytea NOT NULL, content_reference uuid NOT NULL, content_available boolean NOT NULL DEFAULT false, PRIMARY KEY (collection_run_id,database_id,query_fingerprint,content_reference), CHECK (octet_length(query_fingerprint)=32));
CREATE TABLE events.query_performance_database_status (collection_run_id uuid NOT NULL REFERENCES events.query_performance_run(collection_run_id) ON DELETE CASCADE, instance_id uuid NOT NULL, database_id integer NOT NULL, status text NOT NULL, source_state text NOT NULL DEFAULT 'unsupported', reason text NOT NULL, fallback_attempted boolean NOT NULL, truncated boolean NOT NULL, loss_kind text NOT NULL DEFAULT 'none', source_rows_read integer NOT NULL, response_bytes integer NOT NULL, minimum_lost_items integer NOT NULL DEFAULT 0, loss_count_is_exact boolean NOT NULL DEFAULT true, minimum_lost_bytes integer NOT NULL DEFAULT 0, PRIMARY KEY (collection_run_id,database_id), CHECK (database_id BETWEEN 1 AND 32767 AND source_state IN ('read_write','read_only','disabled','unsupported','permission_denied','read_failure','timed_out') AND loss_kind IN ('none','source_row_limit','response_byte_limit','output_validation_failure','ingestion_rejection','duplicate_overlap') AND octet_length(reason) BETWEEN 1 AND 128 AND source_rows_read BETWEEN 0 AND 2001 AND response_bytes BETWEEN 0 AND 8388608 AND minimum_lost_items BETWEEN 0 AND 20000 AND minimum_lost_bytes BETWEEN 0 AND 8388608 AND (loss_kind <> 'none' OR (minimum_lost_items = 0 AND minimum_lost_bytes = 0 AND loss_count_is_exact))));
CREATE INDEX ix_query_performance_query_window ON events.query_performance_query(instance_id,database_id,query_fingerprint);

CREATE OR REPLACE FUNCTION control.query_performance_target_claim(p_instance_id uuid) RETURNS boolean
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, control AS $$
SELECT p_instance_id::text = current_setting('sqlobserver.target_scope', true)
   AND (pg_has_role(current_user,'sqlobserver_collector','member') OR pg_has_role(current_user,'sqlobserver_server','member') OR pg_has_role(current_user,'sqlobserver_migrator','member'));
$$;
REVOKE ALL ON FUNCTION control.query_performance_target_claim(uuid) FROM PUBLIC;

