COMMENT ON TABLE events.query_performance_query IS 'Opaque query identity only; raw SQL text, handles, object/database names are never stored.';
CREATE OR REPLACE FUNCTION events.reject_query_performance_mutation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, events AS $fn$
BEGIN
 IF TG_OP IN ('UPDATE','DELETE') AND current_setting('sqlobserver.retention_context', true)='envelope_cascade' AND pg_has_role(current_user,'sqlobserver_migrator','member') THEN RETURN OLD; END IF;
 RAISE EXCEPTION 'query performance evidence is append-only' USING ERRCODE='55000';
END; $fn$;
REVOKE ALL ON FUNCTION events.reject_query_performance_mutation() FROM PUBLIC;
CREATE TRIGGER query_performance_run_append_only BEFORE UPDATE OR DELETE ON events.query_performance_run FOR EACH ROW EXECUTE FUNCTION events.reject_query_performance_mutation();
CREATE TRIGGER query_performance_query_append_only BEFORE UPDATE OR DELETE ON events.query_performance_query FOR EACH ROW EXECUTE FUNCTION events.reject_query_performance_mutation();
CREATE TRIGGER query_performance_plan_append_only BEFORE UPDATE OR DELETE ON events.query_performance_plan FOR EACH ROW EXECUTE FUNCTION events.reject_query_performance_mutation();
CREATE TRIGGER query_performance_observation_append_only BEFORE UPDATE OR DELETE ON events.query_performance_observation FOR EACH ROW EXECUTE FUNCTION events.reject_query_performance_mutation();
CREATE TRIGGER query_performance_link_append_only BEFORE UPDATE OR DELETE ON events.query_performance_content_link FOR EACH ROW EXECUTE FUNCTION events.reject_query_performance_mutation();

CREATE OR REPLACE FUNCTION control.commit_query_performance_collection_run(p_run_id uuid, p_instance_id uuid, p_target_revision bigint, p_completion_digest bytea, p_window_start timestamptz, p_window_end timestamptz, p_source events.query_performance_source, p_source_state text, p_coverage text, p_freshness boolean, p_truncated boolean, p_fence_token bigint, p_payload jsonb) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, control, events, telemetry AS $fn$
DECLARE existing_digest bytea; selected_work_key text; selected_owner uuid; selected_revision bigint; item jsonb; status_item jsonb; db integer; query_id bytea; plan_id bytea; plan_key bytea; start_at timestamptz; end_at timestamptz; observed_at timestamptz; semantics_value text; executions_value bigint; cpu_value bigint; cumulative_executions bigint; cumulative_cpu bigint; duration_value bigint; reads_value bigint; writes_value bigint; rows_value bigint; prior_executions bigint; prior_cpu bigint; reset_value boolean;
BEGIN
 IF p_run_id IS NULL OR p_instance_id IS NULL OR p_target_revision <= 0 OR p_fence_token <= 0 OR octet_length(p_completion_digest) <> 32 OR p_window_end <= p_window_start OR p_window_end-p_window_start > interval '7 days' OR jsonb_typeof(p_payload) <> 'object' OR jsonb_typeof(p_payload->'observations') <> 'array' OR jsonb_array_length(p_payload->'observations') > 20000 OR jsonb_typeof(p_payload->'databaseStatuses') <> 'array' OR jsonb_array_length(p_payload->'databaseStatuses') > 256 OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'databaseStatuses') value GROUP BY value->>'databaseId' HAVING count(*) > 1) OR octet_length(convert_to(p_payload::text,'UTF8')) > 8388608 OR p_source_state NOT IN ('read_write','read_only','disabled','unsupported','permission_denied','read_failure','timed_out','mixed','unavailable') OR p_coverage NOT IN ('complete','truncated','unavailable','no_activity') OR (p_payload ? 'targetStatus' AND (jsonb_typeof(p_payload->'targetStatus') <> 'object' OR p_payload->'targetStatus'->>'status' IS NULL OR p_payload->'targetStatus'->>'reason' IS NULL)) THEN RAISE EXCEPTION 'query performance commit preflight failed' USING ERRCODE='22023'; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value GROUP BY value->>'databaseId' HAVING count(DISTINCT value->>'queryFingerprint') > 2000) OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value GROUP BY value->>'databaseId',value->>'queryFingerprint' HAVING count(*) > 20000 OR count(DISTINCT NULLIF(value->>'planFingerprint','')) > 50) OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value WHERE jsonb_typeof(value) <> 'object' OR EXISTS (SELECT 1 FROM jsonb_object_keys(value) key WHERE key NOT IN ('databaseId','queryFingerprint','planFingerprint','source','sourceState','semantics','intervalStartUtc','intervalEndUtc','observedAtUtc','cpuMs','durationMs','executions','logicalReads','writes','rows','coverage','fresh','truncated'))) OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value WHERE value->>'databaseId' !~ '^[0-9]+$') OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value WHERE value->>'queryFingerprint' IS NULL OR value->>'queryFingerprint' !~ '^[0-9a-fA-F]{64}$') OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value WHERE value->>'source' NOT IN ('query_store','plan_cache') OR value->>'sourceState' IS NULL OR value->>'sourceState' NOT IN ('read_write','read_only','disabled','unsupported','permission_denied','read_failure','timed_out') OR (p_source <> 'mixed' AND value->>'source' IS DISTINCT FROM p_source::text) OR ((value->>'source')='query_store' AND value->>'semantics' <> 'query_store_interval') OR ((value->>'source')='plan_cache' AND value->>'semantics' = 'query_store_interval')) OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value WHERE value->>'planFingerprint' IS NOT NULL AND value->>'planFingerprint' <> '' AND value->>'planFingerprint' !~ '^[0-9a-fA-F]{64}$') THEN RAISE EXCEPTION 'query performance payload shape or cap invalid' USING ERRCODE='22023'; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value WHERE (value->>'intervalStartUtc')::timestamptz < p_window_start OR (value->>'intervalEndUtc')::timestamptz > p_window_end) THEN RAISE EXCEPTION 'query performance observation is outside requested window' USING ERRCODE='22023'; END IF;
 IF jsonb_array_length(p_payload->'observations') > 0 AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') value WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'databaseStatuses') status_value WHERE status_value->>'databaseId'=value->>'databaseId')) THEN RAISE EXCEPTION 'query performance observation status is missing' USING ERRCODE='22023'; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') observation_value JOIN LATERAL (SELECT value AS status_value FROM jsonb_array_elements(p_payload->'databaseStatuses') value WHERE value->>'databaseId'=observation_value->>'databaseId') status_row ON true WHERE (status_row.status_value->>'status'='query_store_rows' AND (observation_value->>'source')<>'query_store') OR (status_row.status_value->>'status'='plan_cache_rows' AND (observation_value->>'source')<>'plan_cache') OR status_row.status_value->>'status' NOT IN ('query_store_rows','plan_cache_rows')) THEN RAISE EXCEPTION 'query performance observation source and status mismatch' USING ERRCODE='22023'; END IF;
 IF NOT control.query_performance_target_claim(p_instance_id) THEN RAISE EXCEPTION 'query performance target claim missing' USING ERRCODE='42501'; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'databaseStatuses') status_value WHERE
      ((status_value->>'status') IN ('query_store_empty','query_store_disabled','query_store_unsupported','query_store_permission_denied','query_store_read_failure','query_store_timed_out','plan_cache_empty','plan_cache_permission_denied','plan_cache_read_failure','plan_cache_timed_out','output_capped') AND EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') observation_value WHERE observation_value->>'databaseId'=status_value->>'databaseId'))
   OR ((status_value->>'status')='query_store_rows' AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') observation_value WHERE observation_value->>'databaseId'=status_value->>'databaseId' AND observation_value->>'source'='query_store'))
   OR ((status_value->>'status')='plan_cache_rows' AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p_payload->'observations') observation_value WHERE observation_value->>'databaseId'=status_value->>'databaseId' AND observation_value->>'source'='plan_cache')))
 THEN RAISE EXCEPTION 'query performance status and observation source mismatch' USING ERRCODE='22023'; END IF;
 SELECT work_key,owner_execution_id,target_revision INTO selected_work_key,selected_owner,selected_revision FROM telemetry.collection_run WHERE run_id=p_run_id AND instance_id=p_instance_id AND collector_id='queries.performance' FOR UPDATE;
 IF selected_work_key IS NULL OR selected_owner IS NULL OR selected_revision <> p_target_revision THEN RAISE EXCEPTION 'query performance active run or target revision missing' USING ERRCODE='55000'; END IF;
 PERFORM control.assert_worker_lease(selected_work_key,selected_owner,p_fence_token);
 IF NOT EXISTS (SELECT 1 FROM control.collector_schedule WHERE instance_id=p_instance_id AND collector_id='queries.performance' AND active_run_id=p_run_id AND target_revision=p_target_revision) THEN RAISE EXCEPTION 'query performance schedule fence missing' USING ERRCODE='55000'; END IF;
 SELECT completion_digest INTO existing_digest FROM events.query_performance_run WHERE collection_run_id=p_run_id FOR SHARE;
 IF existing_digest IS NOT NULL THEN IF existing_digest <> p_completion_digest THEN RAISE EXCEPTION 'query performance replay digest mismatch' USING ERRCODE='40001'; END IF; RETURN true; END IF;
 INSERT INTO events.query_performance_run(collection_run_id,instance_id,target_revision,window_start,window_end,source,source_state,coverage,freshness,truncated,target_status,target_reason,completion_digest) VALUES(p_run_id,p_instance_id,p_target_revision,p_window_start,p_window_end,p_source,p_source_state,p_coverage,p_freshness,p_truncated,p_payload->'targetStatus'->>'status',p_payload->'targetStatus'->>'reason',p_completion_digest);
 FOR status_item IN SELECT value FROM jsonb_array_elements(p_payload->'databaseStatuses') LOOP
   IF jsonb_typeof(status_item)<>'object' OR status_item->>'databaseId' !~ '^[0-9]+$' OR status_item->>'status' NOT IN ('query_store_empty','query_store_rows','query_store_disabled','query_store_unsupported','query_store_permission_denied','query_store_read_failure','query_store_timed_out','plan_cache_rows','plan_cache_empty','plan_cache_permission_denied','plan_cache_read_failure','plan_cache_timed_out','output_capped') OR status_item->>'fallbackAttempted' IS NULL OR ((status_item->>'status') LIKE 'query_store_%' AND (status_item->>'fallbackAttempted')::boolean) OR ((status_item->>'status') LIKE 'plan_cache_%' AND NOT (status_item->>'fallbackAttempted')::boolean) OR status_item->>'sourceState' IS NULL OR status_item->>'sourceState' NOT IN ('read_write','read_only','disabled','unsupported','permission_denied','read_failure','timed_out') OR ((status_item->>'status') IN ('query_store_rows','query_store_empty') AND status_item->>'sourceState' NOT IN ('read_write','read_only')) OR status_item->>'lossKind' NOT IN ('none','source_row_limit','response_byte_limit','output_validation_failure','ingestion_rejection','duplicate_overlap') OR status_item->>'reason' IS NULL OR status_item->>'truncated' IS NULL OR status_item->>'sourceRowsRead' IS NULL OR status_item->>'responseBytes' IS NULL OR ((status_item->>'status') NOT IN ('query_store_rows','plan_cache_rows','output_capped') AND (status_item->>'lossKind' IN ('source_row_limit','response_byte_limit') OR (status_item->>'truncated')::boolean AND status_item->>'lossKind' = 'none')) OR NOT ((status_item->>'status'='query_store_empty' AND status_item->>'reason'='query_store_empty') OR (status_item->>'status'='query_store_rows' AND status_item->>'reason' IN ('query_store_read','query_store_empty')) OR (status_item->>'status'='query_store_disabled' AND status_item->>'reason'='query_store_disabled') OR (status_item->>'status'='query_store_unsupported' AND status_item->>'reason' IN ('query_store_unsupported','query_store_probe_missing')) OR (status_item->>'status'='query_store_permission_denied' AND status_item->>'reason'='query_store_permission_denied') OR (status_item->>'status'='query_store_read_failure' AND status_item->>'reason'='query_store_read_failure') OR (status_item->>'status'='query_store_timed_out' AND status_item->>'reason'='query_store_timeout') OR (status_item->>'status'='plan_cache_rows' AND status_item->>'reason'='plan_cache_fallback') OR (status_item->>'status'='plan_cache_empty' AND status_item->>'reason'='plan_cache_empty') OR (status_item->>'status'='plan_cache_permission_denied' AND status_item->>'reason'='plan_cache_permission_denied') OR (status_item->>'status'='plan_cache_read_failure' AND status_item->>'reason'='plan_cache_read_failure') OR (status_item->>'status'='plan_cache_timed_out' AND status_item->>'reason'='plan_cache_timeout') OR (status_item->>'status'='output_capped' AND status_item->>'reason'='output_capped')) OR octet_length(status_item->>'reason')>128 OR (status_item->>'sourceRowsRead')::integer NOT BETWEEN 0 AND 2001 OR (status_item->>'responseBytes')::integer NOT BETWEEN 0 AND 8388608 THEN RAISE EXCEPTION 'query performance database status shape invalid' USING ERRCODE='22023'; END IF;
   IF COALESCE((status_item->>'minimumLostItems')::integer,0) NOT BETWEEN 0 AND 20000 OR COALESCE((status_item->>'minimumLostBytes')::integer,0) NOT BETWEEN 0 AND 8388608 OR status_item->>'lossKind'='none' AND (COALESCE((status_item->>'minimumLostItems')::integer,0)<>0 OR COALESCE((status_item->>'minimumLostBytes')::integer,0)<>0 OR COALESCE((status_item->>'lossCountIsExact')::boolean,true)<>true) OR status_item->>'lossKind'<>'none' AND COALESCE((status_item->>'minimumLostItems')::integer,0)=0 AND COALESCE((status_item->>'minimumLostBytes')::integer,0)=0 AND COALESCE((status_item->>'lossCountIsExact')::boolean,true)=true THEN RAISE EXCEPTION 'query performance database status loss detail invalid' USING ERRCODE='22023'; END IF;
   INSERT INTO events.query_performance_database_status(collection_run_id,instance_id,database_id,status,source_state,reason,fallback_attempted,truncated,loss_kind,source_rows_read,response_bytes,minimum_lost_items,loss_count_is_exact,minimum_lost_bytes) VALUES(p_run_id,p_instance_id,(status_item->>'databaseId')::integer,status_item->>'status',status_item->>'sourceState',status_item->>'reason',(status_item->>'fallbackAttempted')::boolean,(status_item->>'truncated')::boolean,status_item->>'lossKind',(status_item->>'sourceRowsRead')::integer,(status_item->>'responseBytes')::integer,COALESCE((status_item->>'minimumLostItems')::integer,0),COALESCE((status_item->>'lossCountIsExact')::boolean,true),COALESCE((status_item->>'minimumLostBytes')::integer,0));
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(p_payload->'observations') LOOP
   IF jsonb_typeof(item) <> 'object' OR item->>'databaseId' !~ '^[0-9]+$' OR (item->>'queryFingerprint') !~ '^[0-9a-fA-F]{64}$' OR (item->>'intervalStartUtc') IS NULL OR (item->>'intervalEndUtc') IS NULL THEN RAISE EXCEPTION 'query performance observation shape invalid' USING ERRCODE='22023'; END IF;
   db := (item->>'databaseId')::integer; query_id := decode(item->>'queryFingerprint','hex'); plan_id := CASE WHEN item->>'planFingerprint' IS NULL OR item->>'planFingerprint'='' THEN NULL ELSE decode(item->>'planFingerprint','hex') END; start_at := (item->>'intervalStartUtc')::timestamptz; end_at := (item->>'intervalEndUtc')::timestamptz; observed_at := COALESCE((item->>'observedAtUtc')::timestamptz,clock_timestamp()); semantics_value := COALESCE(item->>'semantics','query_store_interval'); executions_value := NULLIF(item->>'executions','')::bigint; cpu_value := NULLIF(item->>'cpuMs','')::bigint; duration_value := NULLIF(item->>'durationMs','')::bigint; reads_value := NULLIF(item->>'logicalReads','')::bigint; writes_value := NULLIF(item->>'writes','')::bigint; rows_value := NULLIF(item->>'rows','')::bigint;
   IF db NOT BETWEEN 1 AND 32767 OR octet_length(query_id)<>32 OR (plan_id IS NOT NULL AND octet_length(plan_id)<>32) OR end_at<=start_at OR end_at-start_at>interval '7 days' OR semantics_value NOT IN ('query_store_interval','plan_cache_cumulative','plan_cache_delta','plan_cache_baseline','reset') THEN RAISE EXCEPTION 'query performance observation bounds invalid' USING ERRCODE='22023'; END IF;
   INSERT INTO events.query_performance_query(collection_run_id,instance_id,database_id,query_fingerprint) VALUES(p_run_id,p_instance_id,db,query_id) ON CONFLICT DO NOTHING;
   IF plan_id IS NOT NULL THEN INSERT INTO events.query_performance_plan(collection_run_id,database_id,query_fingerprint,plan_fingerprint) VALUES(p_run_id,db,query_id,plan_id) ON CONFLICT DO NOTHING; END IF;
   IF (item->>'source')='plan_cache' AND semantics_value IN ('plan_cache_cumulative','plan_cache_delta','plan_cache_baseline','reset') THEN
     cumulative_executions := executions_value;
     cumulative_cpu := cpu_value;
     plan_key := coalesce(plan_id,decode(repeat('00',32),'hex'));
     SELECT cumulative_executions,cumulative_cpu_ms INTO prior_executions,prior_cpu FROM events.query_performance_cache_baseline WHERE instance_id=p_instance_id AND database_id=db AND query_fingerprint=query_id AND plan_fingerprint=plan_key FOR UPDATE;
     reset_value := cumulative_executions IS NULL OR cumulative_cpu IS NULL OR prior_executions IS NULL OR prior_cpu IS NULL OR cumulative_executions < prior_executions OR cumulative_cpu < prior_cpu;
     IF reset_value THEN
       semantics_value := CASE WHEN prior_executions IS NULL OR prior_cpu IS NULL THEN 'plan_cache_baseline' ELSE 'reset' END;
     ELSE
       -- Keep the persisted representation cumulative until every supported
       -- counter (duration, reads, writes and rows) has a matching baseline.
       -- A partial delta would mislabel the remaining cumulative fields.
       executions_value := cumulative_executions;
       cpu_value := cumulative_cpu;
       semantics_value := 'plan_cache_cumulative';
     END IF;
     INSERT INTO events.query_performance_cache_baseline(instance_id,database_id,query_fingerprint,plan_fingerprint,cumulative_executions,cumulative_cpu_ms,last_seen_at,reset_generation) VALUES(p_instance_id,db,query_id,plan_key,COALESCE(cumulative_executions,0),COALESCE(cumulative_cpu,0),observed_at,CASE WHEN reset_value AND prior_executions IS NOT NULL THEN 1 ELSE 0 END) ON CONFLICT(instance_id,database_id,query_fingerprint,plan_fingerprint) DO UPDATE SET cumulative_executions=EXCLUDED.cumulative_executions,cumulative_cpu_ms=EXCLUDED.cumulative_cpu_ms,last_seen_at=EXCLUDED.last_seen_at,reset_generation=events.query_performance_cache_baseline.reset_generation+CASE WHEN reset_value THEN 1 ELSE 0 END;
   END IF;
   INSERT INTO events.query_performance_observation(collection_run_id,database_id,query_fingerprint,plan_fingerprint,observation_key,source,source_state,interval_start,interval_end,observed_at,semantics,cpu_ms,duration_ms,execution_count,logical_reads,writes,rows_processed) VALUES(p_run_id,db,query_id,plan_id,decode(substr(md5(coalesce(encode(plan_id,'hex'),'none')||(item->>'source')||start_at::text||end_at::text||observed_at::text),1,32),'hex'),(item->>'source')::events.query_performance_source,coalesce(item->>'sourceState',p_source_state),start_at,end_at,observed_at,semantics_value,cpu_value,duration_value,executions_value,reads_value,writes_value,rows_value) ON CONFLICT DO NOTHING;
 END LOOP;
 -- The canonical control.commit_collection_run call owns schedule, circuit, outcome, and accounting finalization.
 RETURN true;
END; $fn$;
REVOKE ALL ON FUNCTION control.commit_query_performance_collection_run(uuid,uuid,bigint,bytea,timestamptz,timestamptz,events.query_performance_source,text,text,boolean,boolean,bigint,jsonb) FROM PUBLIC,sqlobserver_collector;

-- M7 uses a dedicated canonical lifecycle because the immutable M4 core
-- function intentionally accepts only the three M4 output kinds.  Evidence
-- and this function execute in the same caller transaction; the function is
-- responsible for the collection outcome, visibility gap, schedule and
-- circuit transition, and never makes a non-committed evidence half visible.
CREATE OR REPLACE FUNCTION control.commit_query_performance_collection_run_canonical(
 p_run_id uuid,p_instance_id uuid,p_target_revision bigint,p_collector_version integer,p_output_schema_version integer,
 p_schedule_revision bigint,p_scheduled_at timestamptz,p_work_key text,p_owner_execution_id uuid,p_fencing_token bigint,
 p_request_digest bytea,p_outcome text,p_reason_code text,p_duration_ms bigint,p_attempt_count integer,p_source_row_count integer,
 p_output_item_count integer,p_response_bytes bigint,p_output_bytes bigint,p_loss_kind text,p_minimum_lost_items integer,
 p_loss_count_is_exact boolean,p_minimum_lost_bytes integer,p_next_circuit_state text,p_next_consecutive_failures integer,
 p_completion_digest bytea,p_window_start timestamptz,p_window_end timestamptz,p_source events.query_performance_source,p_source_state text,p_coverage text,p_freshness boolean,p_truncated boolean,p_payload jsonb)
RETURNS TABLE(result_status text,inserted_count integer,duplicate_count integer,rejected_count integer,persisted_bytes integer,committed_at timestamptz)
LANGUAGE plpgsql SECURITY DEFINER VOLATILE SET search_path = pg_catalog,control,events,telemetry AS $fn$
DECLARE run_row telemetry.collection_run%ROWTYPE; outcome_row telemetry.collection_run_outcome%ROWTYPE; schedule_row control.collector_schedule%ROWTYPE; contract_row control.collector_contract%ROWTYPE; now_utc timestamptz := clock_timestamp(); item_count integer := 0; bytes_count integer := 0; completion bytea;
BEGIN
 IF p_run_id IS NULL OR p_instance_id IS NULL OR p_target_revision<=0 OR p_collector_version<>1 OR p_output_schema_version<>1 OR p_fencing_token<=0 OR octet_length(p_request_digest)<>32 OR octet_length(p_completion_digest)<>32 OR jsonb_typeof(p_payload)<>'object' OR jsonb_typeof(p_payload->'observations')<>'array' OR jsonb_typeof(p_payload->'databaseStatuses')<>'array' OR p_outcome NOT IN ('succeeded','partial','timed_out','transient_failure','permanent_failure','permission_denied','unsupported','output_invalid','lease_lost','circuit_open') OR p_reason_code IS NULL OR ((p_attempt_count=0 AND p_outcome<>'circuit_open') OR (p_outcome='circuit_open' AND p_attempt_count<>0) OR (p_outcome NOT IN ('circuit_open') AND p_attempt_count NOT BETWEEN 1 AND 2)) OR p_source_row_count NOT BETWEEN 0 AND 512256 OR p_output_item_count NOT BETWEEN 0 AND 20000 OR p_response_bytes NOT BETWEEN 0 AND 8388608 OR p_output_bytes NOT BETWEEN 0 AND 8388608 OR p_loss_kind NOT IN ('none','source_row_limit','response_byte_limit','output_validation_failure','ingestion_rejection','duplicate_overlap') OR p_minimum_lost_items NOT BETWEEN 0 AND 20000 OR p_minimum_lost_bytes NOT BETWEEN 0 AND 8388608 OR p_next_circuit_state NOT IN ('closed','open','half_open') OR p_next_consecutive_failures NOT BETWEEN 0 AND 1000000 OR (p_outcome='succeeded' AND (p_loss_kind<>'none' OR p_reason_code<>'completed')) OR (p_outcome='partial' AND p_loss_kind='none') OR (p_outcome='circuit_open' AND (p_loss_kind<>'none' OR p_reason_code<>'circuit_currently_open')) OR (p_outcome='lease_lost' AND (p_loss_kind<>'none' OR p_reason_code<>'lease_ownership_lost')) OR (p_outcome='output_invalid' AND (p_loss_kind<>'output_validation_failure' OR p_reason_code<>'output_validation_failed')) OR (p_outcome='timed_out' AND (p_loss_kind<>'none' OR p_reason_code<>'deadline_exceeded')) OR (p_outcome='transient_failure' AND (p_loss_kind<>'none' OR p_reason_code<>'transient_target_failure')) OR (p_outcome='permanent_failure' AND (p_loss_kind<>'none' OR p_reason_code<>'permanent_target_failure')) OR (p_outcome='permission_denied' AND (p_loss_kind<>'none' OR p_reason_code<>'required_permission_missing')) OR (p_outcome='unsupported' AND (p_loss_kind<>'none' OR p_reason_code NOT IN ('target_unsupported','target_version_unsupported','target_platform_unsupported','target_edition_unsupported','capability_missing','capability_profile_missing','capability_profile_stale'))) OR (p_outcome NOT IN ('succeeded','partial') AND jsonb_array_length(p_payload->'observations')<>0) OR (p_outcome NOT IN ('succeeded','partial') AND (jsonb_typeof(p_payload->'targetStatus')<>'object' OR p_payload->'targetStatus'->>'status' IS NULL OR p_payload->'targetStatus'->>'reason' IS NULL)) THEN RAISE EXCEPTION 'query performance canonical preflight failed' USING ERRCODE='22023'; END IF;
 SELECT * INTO run_row FROM telemetry.collection_run WHERE run_id=p_run_id FOR UPDATE;
 IF NOT FOUND OR run_row.instance_id<>p_instance_id OR run_row.target_revision<>p_target_revision OR run_row.collector_id<>'queries.performance' OR run_row.collector_version<>p_collector_version OR run_row.output_schema_version<>p_output_schema_version OR run_row.schedule_revision<>p_schedule_revision OR run_row.work_key<>p_work_key OR run_row.owner_execution_id<>p_owner_execution_id OR run_row.fencing_token<>p_fencing_token OR run_row.request_digest<>p_request_digest THEN RAISE EXCEPTION 'query performance canonical run identity or request digest mismatch' USING ERRCODE='55000'; END IF;
 SELECT * INTO outcome_row FROM telemetry.collection_run_outcome WHERE run_id=p_run_id FOR UPDATE;
 IF FOUND THEN
   IF coalesce((SELECT completion_digest FROM events.query_performance_run WHERE collection_run_id=p_run_id),(SELECT completion_digest FROM telemetry.collection_run_outcome WHERE run_id=p_run_id)) IS DISTINCT FROM p_completion_digest THEN RAISE EXCEPTION 'query performance replay digest mismatch' USING ERRCODE='40001'; END IF;
   RETURN QUERY SELECT 'replayed',outcome_row.inserted_item_count,outcome_row.duplicate_item_count,outcome_row.rejected_item_count,outcome_row.persisted_bytes::integer,outcome_row.completed_at; RETURN;
 END IF;
 IF octet_length(p_completion_digest) <> 32 OR (p_outcome NOT IN ('succeeded','partial') AND coalesce(jsonb_array_length(p_payload->'observations'),0) <> 0) THEN RAISE EXCEPTION 'query performance completion evidence is invalid for outcome' USING ERRCODE='22023'; END IF;
 PERFORM control.assert_worker_lease(p_work_key,p_owner_execution_id,p_fencing_token);
 IF p_outcome IN ('succeeded','partial') OR jsonb_array_length(p_payload->'databaseStatuses') > 0 THEN PERFORM control.commit_query_performance_collection_run(p_run_id,p_instance_id,p_target_revision,p_completion_digest,p_window_start,p_window_end,p_source,p_source_state,p_coverage,p_freshness,p_truncated,p_fencing_token,p_payload); ELSE INSERT INTO events.query_performance_run(collection_run_id,instance_id,target_revision,window_start,window_end,source,source_state,coverage,freshness,truncated,target_status,target_reason,completion_digest) VALUES(p_run_id,p_instance_id,p_target_revision,p_window_start,p_window_end,p_source,p_source_state,p_coverage,p_freshness,p_truncated,p_payload->'targetStatus'->>'status',p_payload->'targetStatus'->>'reason',p_completion_digest); END IF;
 SELECT * INTO schedule_row FROM control.collector_schedule WHERE instance_id=p_instance_id AND collector_id='queries.performance' FOR UPDATE;
 IF NOT FOUND OR schedule_row.active_run_id<>p_run_id OR schedule_row.schedule_revision<>p_schedule_revision OR schedule_row.target_revision<>p_target_revision THEN RAISE EXCEPTION 'query performance schedule fence missing' USING ERRCODE='55000'; END IF;
 SELECT * INTO contract_row FROM control.collector_contract WHERE collector_id='queries.performance' AND collector_version=1;
 IF NOT FOUND THEN RAISE EXCEPTION 'query performance contract missing' USING ERRCODE='55000'; END IF;
 SELECT count(*)::integer,coalesce(sum(256),0)::integer INTO item_count,bytes_count FROM events.query_performance_observation WHERE collection_run_id=p_run_id;
 IF item_count>p_output_item_count OR p_output_item_count-item_count>20000 THEN RAISE EXCEPTION 'query performance output accounting mismatch' USING ERRCODE='22023'; END IF;
 completion := p_completion_digest;
 INSERT INTO telemetry.collection_run_outcome(run_id,outcome,reason_code,attempt_count,retry_count,duration_ms,source_row_count,output_item_count,inserted_item_count,duplicate_item_count,rejected_item_count,response_bytes,output_bytes,persisted_bytes,truncated,loss_detected,loss_kind,loss_count_exact,lost_row_count,lost_byte_count,completion_digest,completed_at) VALUES(p_run_id,p_outcome,p_reason_code,p_attempt_count,greatest(p_attempt_count-1,0),p_duration_ms,p_source_row_count,p_output_item_count,item_count,p_output_item_count-item_count,0,p_response_bytes,p_output_bytes,bytes_count,p_loss_kind IN ('source_row_limit','response_byte_limit','duplicate_overlap'),p_loss_kind<>'none',p_loss_kind,p_loss_count_is_exact,p_minimum_lost_items,p_minimum_lost_bytes,completion,now_utc);
 IF p_outcome<>'succeeded' OR p_loss_kind<>'none' THEN INSERT INTO telemetry.visibility_gap(gap_id,run_id,instance_id,collector_id,reason_code,gap_started_at,gap_ended_at,lost_row_count,lost_byte_count,count_is_exact,recorded_at) VALUES(gen_random_uuid(),p_run_id,p_instance_id,'queries.performance',p_reason_code,p_scheduled_at,now_utc,greatest(p_minimum_lost_items,CASE WHEN p_outcome='succeeded' THEN 0 ELSE 1 END),p_minimum_lost_bytes,p_loss_count_is_exact,now_utc); END IF;
 IF (p_outcome IN ('succeeded','partial') AND (p_next_circuit_state<>'closed' OR p_next_consecutive_failures<>0)) OR (p_outcome IN ('timed_out','transient_failure') AND (p_next_consecutive_failures<>schedule_row.consecutive_failure_count+1 OR p_next_circuit_state<>CASE WHEN schedule_row.circuit_state='half_open' OR schedule_row.consecutive_failure_count+1>=contract_row.circuit_failure_threshold THEN 'open' ELSE 'closed' END)) OR (p_outcome='circuit_open' AND (p_next_circuit_state<>'open' OR p_next_consecutive_failures<>schedule_row.consecutive_failure_count)) OR (p_outcome NOT IN ('succeeded','partial','timed_out','transient_failure','circuit_open') AND (p_next_circuit_state<>'closed' OR p_next_consecutive_failures<>0)) THEN RAISE EXCEPTION 'query performance circuit transition differs from schedule' USING ERRCODE='22023'; END IF;
 UPDATE control.collector_schedule SET active_run_id=NULL,next_due_at=CASE WHEN p_next_circuit_state='open' THEN now_utc+contract_row.circuit_open_interval ELSE now_utc+collection_interval END,circuit_state=p_next_circuit_state,consecutive_failure_count=p_next_consecutive_failures,circuit_open_until=CASE WHEN p_next_circuit_state='open' THEN now_utc+contract_row.circuit_open_interval ELSE NULL END,last_completed_at=now_utc,last_succeeded_at=CASE WHEN p_outcome='succeeded' THEN now_utc ELSE last_succeeded_at END,last_outcome=p_outcome,updated_at=now_utc WHERE instance_id=p_instance_id AND collector_id='queries.performance';
 PERFORM control.assert_worker_lease(p_work_key,p_owner_execution_id,p_fencing_token);
 RETURN QUERY SELECT 'committed',item_count,p_output_item_count-item_count,0,bytes_count,now_utc;
END; $fn$;
REVOKE ALL ON FUNCTION control.commit_query_performance_collection_run(uuid,uuid,bigint,bytea,timestamptz,timestamptz,events.query_performance_source,text,text,boolean,boolean,bigint,jsonb) FROM sqlobserver_collector;
REVOKE ALL ON FUNCTION control.commit_query_performance_collection_run_canonical(uuid,uuid,bigint,integer,integer,bigint,timestamptz,text,uuid,bigint,bytea,text,text,bigint,integer,integer,integer,bigint,bigint,text,integer,boolean,integer,text,integer,bytea,timestamptz,timestamptz,events.query_performance_source,text,text,boolean,boolean,jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION control.commit_query_performance_collection_run_canonical(uuid,uuid,bigint,integer,integer,bigint,timestamptz,text,uuid,bigint,bytea,text,text,bigint,integer,integer,integer,bigint,bigint,text,integer,boolean,integer,text,integer,bytea,timestamptz,timestamptz,events.query_performance_source,text,text,boolean,boolean,jsonb) TO sqlobserver_collector;

DROP FUNCTION IF EXISTS control.get_query_performance_status(uuid,timestamptz,timestamptz);
CREATE OR REPLACE FUNCTION control.get_query_performance_status(p_instance_id uuid, p_from_utc timestamptz, p_to_utc timestamptz) RETURNS TABLE(source events.query_performance_source, source_state text, coverage text, freshness boolean, truncated boolean, repository_time_utc timestamptz, database_statuses jsonb, target_status text, target_reason text)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, control, events AS $fn$ BEGIN IF p_from_utc IS NULL OR p_to_utc IS NULL OR p_to_utc<=p_from_utc OR p_to_utc-p_from_utc>interval '7 days' THEN RAISE EXCEPTION 'query performance status window invalid' USING ERRCODE='22023'; END IF; RETURN QUERY SELECT r.source,r.source_state,r.coverage,r.freshness,r.truncated,r.committed_at,COALESCE((SELECT jsonb_agg(jsonb_build_object('databaseId',s.database_id,'status',s.status,'sourceState',s.source_state,'reason',s.reason,'fallbackAttempted',s.fallback_attempted,'truncated',s.truncated,'lossKind',s.loss_kind,'sourceRowsRead',s.source_rows_read,'responseBytes',s.response_bytes,'minimumLostItems',s.minimum_lost_items,'lossCountIsExact',s.loss_count_is_exact,'minimumLostBytes',s.minimum_lost_bytes) ORDER BY s.database_id) FROM events.query_performance_database_status s WHERE s.collection_run_id=r.collection_run_id),'[]'::jsonb),r.target_status,r.target_reason FROM events.query_performance_run r WHERE r.instance_id=p_instance_id AND control.query_performance_target_claim(p_instance_id) AND r.window_end > p_from_utc AND r.window_start < p_to_utc ORDER BY r.committed_at DESC LIMIT 1; END; $fn$;
CREATE OR REPLACE FUNCTION control.list_query_performance(p_instance_id uuid, p_from_utc timestamptz, p_to_utc timestamptz, p_limit integer, p_after_database_id integer, p_after_interval_end timestamptz, p_after_query bytea) RETURNS SETOF events.query_performance_observation
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, control, events AS $fn$ BEGIN IF p_limit IS NULL OR p_limit<=0 OR p_limit>200 OR p_from_utc IS NULL OR p_to_utc IS NULL OR p_to_utc<=p_from_utc OR p_to_utc-p_from_utc>interval '7 days' THEN RAISE EXCEPTION 'query performance list bounds invalid' USING ERRCODE='22023'; END IF; RETURN QUERY SELECT o.* FROM events.query_performance_observation o JOIN events.query_performance_query q USING(collection_run_id,database_id,query_fingerprint) WHERE q.instance_id=p_instance_id AND control.query_performance_target_claim(p_instance_id) AND o.interval_start >= p_from_utc AND o.interval_end <= p_to_utc AND (p_after_query IS NULL OR (o.database_id,o.interval_end,o.query_fingerprint) > (p_after_database_id,p_after_interval_end,p_after_query)) ORDER BY o.database_id,o.interval_end,o.query_fingerprint LIMIT p_limit + 1; END; $fn$;
REVOKE ALL ON FUNCTION control.get_query_performance_status(uuid,timestamptz,timestamptz),control.list_query_performance(uuid,timestamptz,timestamptz,integer,integer,timestamptz,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION control.get_query_performance_status(uuid,timestamptz,timestamptz) TO sqlobserver_server;
CREATE OR REPLACE FUNCTION control.list_query_performance_projection(p_instance_id uuid, p_from_utc timestamptz, p_to_utc timestamptz, p_limit integer, p_after_database_id integer, p_after_interval_end timestamptz, p_after_query bytea) RETURNS TABLE(database_id integer,query_fingerprint bytea,plan_fingerprint bytea,interval_start timestamptz,interval_end timestamptz,observed_at timestamptz,semantics text,cpu_ms bigint,duration_ms bigint,execution_count bigint,logical_reads bigint,writes bigint,rows_processed bigint,source events.query_performance_source,source_state text,coverage text,freshness boolean,truncated boolean,committed_at timestamptz)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, control, events AS $$ SELECT o.database_id,o.query_fingerprint,o.plan_fingerprint,o.interval_start,o.interval_end,o.observed_at,o.semantics,o.cpu_ms,o.duration_ms,o.execution_count,o.logical_reads,o.writes,o.rows_processed,o.source,o.source_state,r.coverage,r.freshness,r.truncated,r.committed_at FROM control.list_query_performance(p_instance_id,p_from_utc,p_to_utc,p_limit,p_after_database_id,p_after_interval_end,p_after_query) o JOIN events.query_performance_run r ON r.collection_run_id=o.collection_run_id $$;
REVOKE ALL ON FUNCTION control.list_query_performance_projection(uuid,timestamptz,timestamptz,integer,integer,timestamptz,bytea) FROM PUBLIC;
CREATE OR REPLACE FUNCTION control.get_top_queries(p_instance_id uuid, p_from_utc timestamptz, p_to_utc timestamptz, p_metric text, p_limit integer, p_after_database_id integer, p_after_interval_end timestamptz, p_after_query bytea) RETURNS SETOF events.query_performance_observation
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, control, events AS $fn$ BEGIN IF p_limit IS NULL OR p_limit<=0 OR p_limit>200 OR p_metric NOT IN ('cpu','duration','executions','logical_reads','writes','rows') OR p_from_utc IS NULL OR p_to_utc IS NULL OR p_to_utc<=p_from_utc OR p_to_utc-p_from_utc>interval '7 days' THEN RAISE EXCEPTION 'query performance top bounds invalid' USING ERRCODE='22023'; END IF; RETURN QUERY SELECT * FROM control.list_query_performance(p_instance_id,p_from_utc,p_to_utc,p_limit,p_after_database_id,p_after_interval_end,p_after_query); END; $fn$;
CREATE OR REPLACE FUNCTION control.get_query_history(p_instance_id uuid, p_database_id integer, p_query_fingerprint bytea, p_from_utc timestamptz, p_to_utc timestamptz, p_limit integer, p_after_interval_end timestamptz) RETURNS SETOF events.query_performance_observation
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, control, events AS $fn$ BEGIN IF p_limit IS NULL OR p_limit<=0 OR p_limit>200 OR p_database_id IS NULL OR p_database_id<=0 OR p_query_fingerprint IS NULL OR octet_length(p_query_fingerprint)<>32 OR p_from_utc IS NULL OR p_to_utc IS NULL OR p_to_utc<=p_from_utc OR p_to_utc-p_from_utc>interval '7 days' THEN RAISE EXCEPTION 'query performance history bounds invalid' USING ERRCODE='22023'; END IF; RETURN QUERY SELECT o.* FROM events.query_performance_observation o JOIN events.query_performance_query q USING(collection_run_id,database_id,query_fingerprint) WHERE q.instance_id=p_instance_id AND o.database_id=p_database_id AND o.query_fingerprint=p_query_fingerprint AND o.interval_start >= p_from_utc AND o.interval_end <= p_to_utc AND control.query_performance_target_claim(p_instance_id) ORDER BY o.interval_end,o.collection_run_id LIMIT p_limit; END; $fn$;
CREATE OR REPLACE FUNCTION control.get_query_plan_metadata(p_instance_id uuid, p_database_id integer, p_query_fingerprint bytea, p_plan_fingerprint bytea) RETURNS TABLE(plan_fingerprint bytea, source events.query_performance_source, observed_at timestamptz, coverage text, content_available boolean)
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = pg_catalog, control, events AS $$ SELECT p.plan_fingerprint,o.source,o.observed_at,r.coverage,false FROM events.query_performance_plan p JOIN events.query_performance_query q USING(collection_run_id,database_id,query_fingerprint) JOIN events.query_performance_observation o ON o.collection_run_id=p.collection_run_id AND o.database_id=p.database_id AND o.query_fingerprint=p.query_fingerprint AND o.plan_fingerprint=p.plan_fingerprint JOIN events.query_performance_run r USING(collection_run_id) WHERE q.instance_id=p_instance_id AND p.database_id=p_database_id AND p.query_fingerprint=p_query_fingerprint AND p.plan_fingerprint=p_plan_fingerprint AND control.query_performance_target_claim(p_instance_id) ORDER BY o.observed_at DESC,o.interval_end DESC,o.collection_run_id DESC,o.observation_key DESC LIMIT 1 $$;
REVOKE ALL ON FUNCTION control.get_top_queries(uuid,timestamptz,timestamptz,text,integer,integer,timestamptz,bytea),control.get_query_history(uuid,integer,bytea,timestamptz,timestamptz,integer,timestamptz),control.get_query_plan_metadata(uuid,integer,bytea,bytea) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION control.get_query_plan_metadata(uuid,integer,bytea,bytea) TO sqlobserver_server;
-- The earlier generic list/top/history projections are intentionally removed;
-- only the snapshot-bound M7 projections below are callable by the server.
DROP FUNCTION IF EXISTS control.list_query_performance_projection(uuid,timestamptz,timestamptz,integer,integer,timestamptz,bytea);
DROP FUNCTION IF EXISTS control.list_query_performance(uuid,timestamptz,timestamptz,integer,integer,timestamptz,bytea);
DROP FUNCTION IF EXISTS control.get_top_queries(uuid,timestamptz,timestamptz,text,integer,integer,timestamptz,bytea);
DROP FUNCTION IF EXISTS control.get_query_history(uuid,integer,bytea,timestamptz,timestamptz,integer,timestamptz);
DROP FUNCTION IF EXISTS control.get_query_history_projection(uuid,integer,bytea,timestamptz,timestamptz,integer,timestamptz,uuid,bytea,bytea,timestamptz);
DROP FUNCTION IF EXISTS control.get_query_history_projection(uuid,integer,bytea,timestamptz,timestamptz,integer,timestamptz,uuid,bytea,timestamptz);
DROP FUNCTION IF EXISTS control.get_query_history_projection(uuid,integer,bytea,timestamptz,timestamptz,integer,timestamptz);
CREATE OR REPLACE FUNCTION control.get_query_history_projection(p_instance_id uuid, p_database_id integer, p_query_fingerprint bytea, p_from_utc timestamptz, p_to_utc timestamptz, p_limit integer, p_after_interval_end timestamptz, p_after_run_id uuid, p_after_plan bytea, p_after_observation_key bytea, p_snapshot_utc timestamptz) RETURNS TABLE(database_id integer,query_fingerprint bytea,plan_fingerprint bytea,interval_start timestamptz,interval_end timestamptz,observed_at timestamptz,semantics text,cpu_ms bigint,duration_ms bigint,execution_count bigint,logical_reads bigint,writes bigint,rows_processed bigint,source events.query_performance_source,source_state text,coverage text,freshness boolean,truncated boolean,committed_at timestamptz,collection_run_id uuid,observation_key bytea)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, control, events AS $fn$
BEGIN
 IF p_limit IS NULL OR p_limit <= 0 OR p_limit > 200 OR p_from_utc IS NULL OR p_to_utc IS NULL OR p_to_utc <= p_from_utc OR p_to_utc-p_from_utc > interval '7 days' OR p_snapshot_utc IS NULL OR p_database_id <= 0 OR p_query_fingerprint IS NULL OR octet_length(p_query_fingerprint) <> 32 THEN RAISE EXCEPTION 'query performance history projection bounds invalid' USING ERRCODE='22023'; END IF;
 RETURN QUERY SELECT o.database_id,o.query_fingerprint,o.plan_fingerprint,o.interval_start,o.interval_end,o.observed_at,o.semantics,o.cpu_ms,o.duration_ms,o.execution_count,o.logical_reads,o.writes,o.rows_processed,o.source,o.source_state,r.coverage,r.freshness,r.truncated,r.committed_at,o.collection_run_id,o.observation_key FROM events.query_performance_observation o JOIN events.query_performance_query q USING(collection_run_id,database_id,query_fingerprint) JOIN events.query_performance_run r USING(collection_run_id) WHERE q.instance_id=p_instance_id AND o.database_id=p_database_id AND o.query_fingerprint=p_query_fingerprint AND o.interval_start>=p_from_utc AND o.interval_end<=p_to_utc AND r.committed_at<=p_snapshot_utc AND (p_after_interval_end IS NULL OR (o.interval_end>p_after_interval_end OR (o.interval_end=p_after_interval_end AND (o.collection_run_id>p_after_run_id OR (o.collection_run_id=p_after_run_id AND (coalesce(o.plan_fingerprint,''::bytea)>coalesce(p_after_plan,''::bytea) OR (coalesce(o.plan_fingerprint,''::bytea)=coalesce(p_after_plan,''::bytea) AND o.observation_key>coalesce(p_after_observation_key,''::bytea)))))))) AND control.query_performance_target_claim(p_instance_id) ORDER BY o.interval_end,o.collection_run_id,coalesce(o.plan_fingerprint,''::bytea),o.observation_key LIMIT p_limit + 1;
END; $fn$;
DROP FUNCTION IF EXISTS control.get_top_queries_projection(uuid,timestamptz,timestamptz,text,integer,integer,timestamptz,bytea,bytea,uuid,bigint,bytea,timestamptz);
DROP FUNCTION IF EXISTS control.get_top_queries_projection(uuid,timestamptz,timestamptz,text,integer,integer,timestamptz,bytea,bytea,uuid,bigint,timestamptz);
CREATE OR REPLACE FUNCTION control.get_top_queries_projection(p_instance_id uuid, p_from_utc timestamptz, p_to_utc timestamptz, p_metric text, p_limit integer, p_after_database_id integer, p_after_interval_end timestamptz, p_after_query bytea, p_after_plan bytea, p_after_run_id uuid, p_after_metric bigint, p_after_observation_key bytea, p_snapshot_utc timestamptz) RETURNS TABLE(database_id integer,query_fingerprint bytea,plan_fingerprint bytea,interval_start timestamptz,interval_end timestamptz,observed_at timestamptz,semantics text,cpu_ms bigint,duration_ms bigint,execution_count bigint,logical_reads bigint,writes bigint,rows_processed bigint,source events.query_performance_source,source_state text,coverage text,freshness boolean,truncated boolean,committed_at timestamptz,collection_run_id uuid,observation_key bytea)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = pg_catalog, control, events AS $fn$
BEGIN
 IF p_limit IS NULL OR p_limit <= 0 OR p_limit > 200 OR p_from_utc IS NULL OR p_to_utc IS NULL OR p_to_utc <= p_from_utc OR p_to_utc-p_from_utc > interval '7 days' OR p_snapshot_utc IS NULL OR p_metric NOT IN ('cpu','duration','executions','logical_reads','writes','rows') THEN RAISE EXCEPTION 'query performance top projection bounds invalid' USING ERRCODE='22023'; END IF;
 RETURN QUERY WITH candidates AS MATERIALIZED (SELECT o.database_id,o.query_fingerprint,o.plan_fingerprint,o.interval_start,o.interval_end,o.observed_at,o.semantics,o.cpu_ms,o.duration_ms,o.execution_count,o.logical_reads,o.writes,o.rows_processed,o.source,o.source_state,r.coverage,r.freshness,r.truncated,r.committed_at,o.collection_run_id,o.observation_key,CASE p_metric WHEN 'cpu' THEN o.cpu_ms WHEN 'duration' THEN o.duration_ms WHEN 'executions' THEN o.execution_count WHEN 'logical_reads' THEN o.logical_reads WHEN 'writes' THEN o.writes ELSE o.rows_processed END AS metric_value FROM events.query_performance_observation o JOIN events.query_performance_query q USING(collection_run_id,database_id,query_fingerprint) JOIN events.query_performance_run r USING(collection_run_id) WHERE q.instance_id=p_instance_id AND o.interval_start>=p_from_utc AND o.interval_end<=p_to_utc AND r.committed_at<=p_snapshot_utc AND control.query_performance_target_claim(p_instance_id)) SELECT database_id,query_fingerprint,plan_fingerprint,interval_start,interval_end,observed_at,semantics,cpu_ms,duration_ms,execution_count,logical_reads,writes,rows_processed,source,source_state,coverage,freshness,truncated,committed_at,collection_run_id,observation_key FROM candidates WHERE metric_value IS NOT NULL AND metric_value >= 0 AND (p_after_query IS NULL OR metric_value < p_after_metric OR (metric_value = p_after_metric AND (database_id,interval_end,query_fingerprint,coalesce(plan_fingerprint,''::bytea),collection_run_id,observation_key) > (p_after_database_id,p_after_interval_end,p_after_query,coalesce(p_after_plan,''::bytea),p_after_run_id,coalesce(p_after_observation_key,''::bytea)))) ORDER BY metric_value DESC,database_id,interval_end,query_fingerprint,coalesce(plan_fingerprint,''::bytea),collection_run_id,observation_key LIMIT p_limit + 1;
END; $fn$;
REVOKE ALL ON FUNCTION control.get_query_history_projection(uuid,integer,bytea,timestamptz,timestamptz,integer,timestamptz,uuid,bytea,bytea,timestamptz),control.get_top_queries_projection(uuid,timestamptz,timestamptz,text,integer,integer,timestamptz,bytea,bytea,uuid,bigint,bytea,timestamptz) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION control.get_query_history_projection(uuid,integer,bytea,timestamptz,timestamptz,integer,timestamptz,uuid,bytea,bytea,timestamptz),control.get_top_queries_projection(uuid,timestamptz,timestamptz,text,integer,integer,timestamptz,bytea,bytea,uuid,bigint,bytea,timestamptz) TO sqlobserver_server;

CREATE OR REPLACE FUNCTION control.reconcile_collector_catalog_m7(p_collector_ids text[],p_collector_versions integer[],p_manifest_sha256 bytea[],p_asset_bundle_sha256 bytea[],p_execution_orders integer[],p_work_key text,p_owner_execution_id uuid,p_fencing_token bigint)
RETURNS TABLE(inserted_count integer,updated_count integer,unchanged_count integer,repository_time timestamptz)
LANGUAGE plpgsql SECURITY DEFINER VOLATILE PARALLEL UNSAFE SET search_path=pg_catalog,control AS $fn$
DECLARE captured timestamptz;
BEGIN
 IF p_work_key <> 'collector/catalog/reconcile' OR p_collector_ids IS DISTINCT FROM ARRAY['engine.core','database.inventory','database.files','activity.sessions','activity.requests','waits.server','blocking.current','deadlocks.system-health','queries.performance']::text[] OR p_collector_versions IS DISTINCT FROM ARRAY[1,1,1,1,1,1,1,1,1]::integer[] OR p_execution_orders IS DISTINCT FROM ARRAY[1,2,3,4,5,6,7,8,9]::integer[] OR cardinality(p_manifest_sha256) <> 9 OR cardinality(p_asset_bundle_sha256) <> 9 THEN RAISE EXCEPTION 'collector M7 catalog must contain the exact ordered reviewed contract set' USING ERRCODE='22023'; END IF;
 PERFORM control.assert_worker_lease(p_work_key,p_owner_execution_id,p_fencing_token);
 IF EXISTS (SELECT 1 FROM unnest(p_collector_ids,p_collector_versions,p_manifest_sha256,p_asset_bundle_sha256,p_execution_orders) AS x(id,version,manifest,bundle,execution_order) LEFT JOIN control.collector_contract c ON c.collector_id=x.id AND c.collector_version=x.version AND c.manifest_sha256=x.manifest AND c.asset_bundle_sha256=x.bundle AND c.execution_order=x.execution_order WHERE c.collector_id IS NULL) THEN RAISE EXCEPTION 'collector M7 catalog differs from immutable repository contracts' USING ERRCODE='55000'; END IF;
 captured:=clock_timestamp();
 INSERT INTO control.collector_schedule(instance_id,collector_id,collector_version,target_revision,schedule_revision,enabled,collection_interval,next_due_at,circuit_state,consecutive_failure_count,created_at,updated_at) SELECT target.instance_id,contract.collector_id,contract.collector_version,target.revision,1,true,contract.default_interval,captured,'closed',0,captured,captured FROM control.observation_target target CROSS JOIN control.collector_contract contract WHERE target.host_name IS NOT NULL AND target.lifecycle_state='active' AND contract.collector_id=ANY(p_collector_ids) ON CONFLICT(instance_id,collector_id) DO NOTHING;
 PERFORM control.assert_worker_lease(p_work_key,p_owner_execution_id,p_fencing_token);
 -- Catalog reconciliation counts describe the nine immutable contracts, not
 -- per-target schedule rows created as a side effect of reconciliation.
 RETURN QUERY SELECT 0,0,9,captured;
END; $fn$;
REVOKE ALL ON FUNCTION control.reconcile_collector_catalog_m7(text[],integer[],bytea[],bytea[],integer[],text,uuid,bigint) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION control.reconcile_collector_catalog_m7(text[],integer[],bytea[],bytea[],integer[],text,uuid,bigint) TO sqlobserver_collector;
